import sys

def solve():
    n, k = map(int, sys.stdin.readline().strip().split())
    s = sys.stdin.readline().strip()
    b_count = s.count('B')

    if k == b_count:
        return 0, ''

    operations = []

    if b_count > k:
        A_idx = next((i for i, x in enumerate(s) if x == 'A'), None)

        if A_idx is not None and b_count - A_idx <= k:
            operations.append([n, 'A'])
        else:
            operations.append([s.rfind('B') + 1, 'A'])

    elif k > b_count:
        last_A = s.rfind('A')

        if (last_A is not None) and (b_count + last_A + 1 >= k):
            operations.append([k - b_count + 1, 'B']) 
        else:
            operations.append([n, 'B'])

    return len(operations), '\n'.join(f'{op[0]} {op[1]}' for op in operations)

if __name__ == "__main__":
    test_cases = int(input())
    outputs = [solve() for _ in range(test_cases)]

