    def pair_up(num):
        if num % 2 == 0:
            return (num - 1, num)
        else:
            return (num + 1, num)

    result = []
    i = 1
    while True:
        first, second = pair_up(i)
        if not result or max(first, second) <= n:
            result.append(second)
            result.append(first)
        else:
            break
        i += 2

