import sys

def solve():
	n, m = map(int, sys.stdin.readline().split())
	dp = [[0 for _ in range(m)] for i in range(n)]
	for i in range(n):
		dp[i][0] = (m * i) + 1
	for j in range(1, m):
		dp[0][j] = dp[0][j-1] + 2
	for i in range(1, n):
		for j in range(1, m):
			dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + (m * i) + j + 1
	return str(dp[n-1][m-1])

def main():
    inputs = int(sys.stdin.readline())
    for _ in range(inputs):
        sys.stdout.write(solve() + "\n") 

main()
